// The day's affirmation in Chinese (Simplified), for the country pages in Chinese (Simplified). Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"今天不必把所有事都做完。下一件小事就够了。\", \"累不代表失败。你会累，是因为你每天都在坚持。\", \"碗可以晚点再洗。你可以坐下来歇五分钟。\", \"晚饭吃麦片，也算是喂饱了一家人。\", \"休息不需要先努力才配得到。你现在就可以休息。\", \"有些日子，胜利就是全家人平平安安撑到睡觉。这是真正的胜利。\", \"你做的比任何人看到的都多。我看见了。\", \"家里乱一点，孩子被好好爱着。这笔交换很划算。\", \"难熬的日子里，你的尽力看起来不一样，但一样算数。\", \"深吸一口气。放松肩膀。你做得很好。\", \"今天把标准放低一点没关系。改天再调回来就好。\", \"开口求助是坚强，不是软弱。\", \"你可以对再多一件事说“不”。\", \"如果今天觉得孤单，你不是唯一有这种感觉的妈妈。我们有很多人。\", \"你值得有一个朋友，问你过得好不好，并且真的等你回答。\", \"先开口联系也没关系。很多妈妈都在等别人先开口。\", \"觉得没人看见，不代表你不重要。你非常重要。\", \"你的感受是有道理的。你一点也不过分。\", \"在这里，你不用解释你难熬的一天。我们懂。\", \"给另一个妈妈发一句“我也是”，就能让一整天变得不一样。\", \"喂奶、换尿布、哄睡，再来一遍。这是真正的工作，哪怕看起来像是坐着没动。\", \"你和宝宝还在互相熟悉。不用急。\", \"和新生儿在一起的日子很长。这个阶段不会永远持续。\", \"如果今天你只是让一个小小的人吃饱穿暖，你已经完成了一件大事。\", \"你不用急着恢复原来的样子。现在的你，这样就好。\", \"不管宝宝用什么方式喝奶，你都在照顾宝宝。这才是最重要的。\", \"你可以睡眠不足，同时满满都是爱。\", \"抱着宝宝，家务先放一放。家又不会跑掉。\", \"孩子在超市里大哭大闹，不代表你是个坏妈妈。只说明你的孩子还小。\", \"小家伙爱试探底线，是因为在你身边觉得安全。\", \"今天你比昨天多冷静了一分钟。这也算数。\", \"如果你发了脾气，一个拥抱加一句“对不起”能弥补很多。这也教会了孩子一件好事。\", \"黏糊糊的小手、大大的嗓门、大大的情绪。你正在养育一个完整的人。\", \"一个小时里的第五个“为什么？”，说明一个小脑袋正在长大。\", \"不需要完美的一天，也能留下快乐的回忆。\", \"摔上的门不是故事的结局。给孩子留一盏灯。\", \"青春期的孩子也许不会说出口，但你一直都在，这对孩子很重要。\", \"当家里那个保持冷静的人很辛苦。而你做到了。\", \"有些最好的谈心发生在车里。继续开吧。\", \"孩子拉开距离是为了长大，不是要把你丢在身后。\", \"你不需要知道所有答案。倾听就是很大一部分。\", \"大孩子还是需要你，只是方式更安静了。\", \"一个人扛起一切，需要一种大多数人从来看不见的力量。\", \"对你的孩子来说，你已经是足够好的妈妈。一直都是。\", \"一双手，一百件事。对自己温柔一点。\", \"孩子们看着你，学会了一个坚强又有爱的人是什么样子。\", \"休息不是擅离职守。这是你能继续走下去的方法。\", \"没有人在计分。爱和陪伴，才是最重要的。\", \"悲伤和爱来自同一个地方。思念一个人，说明你有多爱。\", \"悲伤没有正确的时间表。你需要多久，就给自己多久。\", \"在难熬的纪念日，像对待朋友一样温柔地对待自己。\", \"你可以带着悲伤，仍然和孩子一起笑。两者都是真的。\", \"如果你失去过一次怀孕或一个宝宝，那份失去是真的，你的爱也是。\", \"有些日子悲伤很安静，有些日子很喧闹。两种都没关系。\", \"钱少，不代表爱少。\", \"孩子会记得和你在一起的时光，胜过你给他们买的东西。\", \"打听账单方面的补助是聪明的做法，不丢人。补助本来就是为此设立的。\", \"在公园度过一个免费的下午，可能就是这周最棒的一天。\", \"你让钱又撑过了一周。这需要真本事。\", \"为钱发愁很累人。你扛着好多，而你还在这里。\", \"你今天喝了一杯水。就从这里开始。\", \"大家都出门了。鞋子也许没配成对。还是一场胜利。\", \"你打了那通你一直害怕的电话。那很勇敢。\", \"你今天笑了。好好留住这份感觉。\", \"一顿热饭、一件干净的衣服、一个睡前故事。小事积累起来，就是一段童年。\", \"今天你对某个人很温柔，哪怕那个人只是你自己。\", \"要进步，不必完美。你今天往前走了。\", \"你完成了清单上的一件事。比一件都没做多了一件。\", \"你是个好妈妈。你会为这件事担心，正说明你有多在乎。\", \"你的价值，远远超过你一天能完成的事。\", \"孩子不需要完美的妈妈。他们需要你，而他们有你。\", \"对自己，要像对孩子一样有耐心。\", \"你可以有自己的空间、自己的渴望和自己的梦想。\", \"一个错误抹不掉爱。明天是新的开始。\", \"你是某个人的整个世界，同时也是独立的自己。\", \"不喜欢每一分钟也没关系。你依然可以全心全意爱你的孩子。\", \"当妈妈没有唯一正确的方式。你的方式也很好。\", \"就像树式一样，晃一晃也没关系。你可以再找回平衡。\", \"像山式一样把双脚踩稳。你比自己感觉的更稳。\", \"战士二式：双腿有力，双臂张开。那就是迎接这一周的你。\", \"吸气数到四，呼气数到四。你就在这里，你做得很好。\", \"像星星一样大大地伸展。你有权利占据空间。\", \"又宽又低的深蹲很难坚持。漫长的一天也是。而你坚持住了。\", \"你可以像一弯新月那样倾斜，依然站得稳稳的。\", \"还不用碰到脚趾。每一点点伸展都算数。\", \"三角式：一手向下，一手向上。站稳脚跟，继续伸展。\", \"已经很晚了。今天没做完的，可以等到明天。\", \"这个时间还陪着宝宝醒着吗？此刻有很多妈妈和你一起醒着。\", \"家里安静下来了。这一刻属于你。好好呼吸。\", \"你撑过了今天。今天需要的就只有这些。\", \"如果今晚脑子停不下来，就写下来，让它等到早上。\", \"让眼睛休息一下。明天你可以重新开始。\", \"节日可能很难熬，也可能很快乐。不论这个季节带给你什么感受，都没关系。\", \"餐桌不必完美。围坐在旁边的人才重要。\", \"如果今年餐桌旁少了一个你想念的人，请温柔对待自己的心。\", \"谢谢你，妈妈，为了每一顿饭、每一次接送和每一个拥抱。\", \"你不必请客、烤点心，也不必一直笑。简单的节日也是节日。\", \"今年孩子们收到的最好的礼物，是和你在一起的时间。\", \"小小的庆祝也充满了爱。不需要很多钱，也能过得很特别。\", \"天气冷，拥抱暖。你就是家里那个温暖的角落。\", \"跳过一些节日的忙乱没关系。平静也是一份礼物。\", \"如果今年这个季节让你觉得沉重，你并不孤单。一天一天慢慢来。\"]";D.body.appendChild(e)})();
